using System.Text;
using CS2Hazirla.Core;
using Xunit;

namespace CS2Hazirla.Tests;

/// <summary>
/// Characterization ("golden") test of WHAT the planner closes and stops. The expected text in Golden\selection.golden.txt was generated by the
/// code of v2.0.0, before any change of this work. Rule of the owner: nothing that is closed / stopped today may stop being closed / stopped.
/// If this test fails after a change, the change altered the selection: that is a bug unless the owner agreed to it explicitly.
/// (To look at the actual output: it is written next to the golden file in the output folder as selection.actual.txt.)
/// </summary>
[Collection("Sequential")]
public class GoldenSelectionTests
{
    // Every option id of v2.0.0, hard-coded on purpose: ids that were removed later simply do nothing now (and must select nothing).
    // ("proc.dpi" was the one switch of Discord, GoodbyeDPI AND the other block-bypass tools; With(...) below sets "proc.discord" and "proc.bypass" together with it.)
    private static readonly string[] BaselineOptionIds =
    {
        "proc.browsers", "proc.cloud", "proc.launchers", "proc.updaters", "proc.oem", "proc.peripherals", "proc.overlay", "proc.vpn",
        "proc.antivirus", "proc.anticheat", "proc.dpi", "proc.windowed", "proc.claude", "proc.chat", "proc.trayauto", "proc.tray", "proc.extra",
        "svc.update", "svc.other", "pwr.plan", "sys.gamemode", "sys.gamedvr", "sys.notifications", "sys.gpupref", "sys.fso", "sys.mouseaccel",
        "sys.hotkeys", "net.flushdns", "net.nicpower", "mem.standby", "misc.temp", "net.nagle",
    };

    private static readonly string[] ExtraProcessList = { "onedrive", "foobar", "ghost-not-running", "steam", "obs64", "TrayWidget.exe" };
    private static readonly string[] NeverCloseList = { "dropbox", "discord", "ZetaDaemon", "SPOTIFY.exe", "chrome" };

    private static FakeSystem BuildMachine()
    {
        var sys = new FakeSystem();
        var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        var n = 0;
        void Add(string name, string? path = null, bool window = false, int session = 1)
        {
            if (!seen.Add(name + "|" + session + "|" + window)) return;
            sys.Procs.Add(new ProcInfo(2000 + n++, name, path ?? $@"C:\Program Files\Vendor {n % 7}\{name}\{name}.exe", session, window, 50L << 20));
        }

        // every exe name of every category, exactly as written in the catalog; every second one has a window
        var i = 0;
        foreach (var cat in Catalog.ProcessCategories)
        {
            foreach (var name in cat.Names) Add(name, window: i++ % 2 == 0);
            // a sample for every prefix and every token rule
            foreach (var p in cat.Prefixes) Add(p + "agent", window: i++ % 3 == 0);
            if (cat.ContainsTokens != null)
                foreach (var t in cat.ContainsTokens) Add("my" + t + "app", window: i++ % 2 == 1);
        }

        // unknown programs without a window (what the "unknown background programs" sweep looks at), with normal paths
        Add("RandomTrayThing"); Add("ZetaDaemon"); Add("TrayWidget", @"C:\Users\x\AppData\Local\Programs\TrayWidget\TrayWidget.exe");
        Add("FooBar", @"D:\Tools\FooBar\foobar.exe"); Add("SyncAgent9000");
        Add("StoreThing", @"C:\Program Files\WindowsApps\Vendor.StoreThing_1.0\StoreThing.exe");            // Store app: left alone
        Add("WinFolderThing", @"C:\Windows\System32\WinFolderThing.exe");                                   // protected by its folder
        // unknown programs with a window (the "open windows" sweep)
        Add("WordLike", window: true); Add("CodeEditor", window: true); Add("NotesApp", window: true);
        Add("HybridApp"); Add("HybridApp", window: true);                                                   // same name: one with, one without window
        // protected (always) and protected only in stream mode
        foreach (var p in new[] { "steam", "steamwebhelper", "svchost", "explorer", "MsMpEng", "FACEITClient", "NVDisplay.Container", "RtkAudUService64", "msedgewebview2" })
            Add(p, window: i++ % 2 == 0);
        foreach (var p in new[] { "obs64", "streamlabs", "voicemeeter", "elgato", "InputOverlay", "streamdeck" }) Add(p, window: true);
        // another Windows session is never touched
        Add("OtherSessionTool", session: 2); Add("chrome", session: 2, window: true);

        // services: every default one running, one that cannot be stopped, one stopped, one with a dependent
        foreach (var r in Catalog.DefaultServices())
            sys.Services[r.Name] = new FakeService { Display = r.Name };
        sys.Services["DoSvc"].CanStop = false;
        sys.Services["WerSvc"].State = ServiceRunState.Stopped;
        sys.Services["Spooler"].Dependents.Add("PrintNotify");
        sys.Services["PrintNotify"] = new FakeService { Display = "Printer Extensions" };
        sys.Services["Audiosrv"] = new FakeService { Display = "Windows Audio" };
        sys.Services["SomeUserSvc"] = new FakeService { Display = "Some user service" };
        return sys;
    }

    private static AppSettings Preset(ProfileKind kind, bool extras)
    {
        var s = new AppSettings();
        s.ApplyProfile(kind);
        if (extras) AddExtras(s);
        return s;
    }

    private static AppSettings With(ProfileKind kind, Func<string, bool> on, bool extras)
    {
        var s = new AppSettings { Profile = kind, Options = BaselineOptionIds.ToDictionary(id => id, on) };
        // v2.0.0 had ONE switch for Discord, GoodbyeDPI and the other block-bypass tools: the golden speaks that language
        s.Options["proc.discord"] = s.Options["proc.dpi"];
        s.Options["proc.bypass"] = s.Options["proc.dpi"];
        if (extras) AddExtras(s);
        return s;
    }

    private static void AddExtras(AppSettings s)
    {
        s.ExtraProcesses.AddRange(ExtraProcessList);
        s.NeverClose.AddRange(NeverCloseList);
        s.Services.Add(new ServiceRule { Name = "Audiosrv", Group = "other" });                       // protected: refused
        s.Services.Add(new ServiceRule { Name = "SomeUserSvc", Group = "other" });
        s.Services.Add(new ServiceRule { Name = "PrintNotify", Group = "update", Enabled = false });  // switched off in the list
    }

    private static string Describe(string label, AppSettings s)
    {
        var plan = new Planner(BuildMachine()).Build(s, TestEnv.Cs2Path);
        string Ids(ActionKind k) => string.Join(",", plan.Active.Where(a => a.Kind == k).Select(a => a.Id).OrderBy(x => x, StringComparer.Ordinal));
        return $"## {label}\nclose: {Ids(ActionKind.CloseProcess)}\nstop: {Ids(ActionKind.StopService)}\n";
    }

    private static string Everything()
    {
        var sb = new StringBuilder();
        foreach (var kind in Enum.GetValues<ProfileKind>())
        {
            sb.Append(Describe($"preset {kind}", Preset(kind, extras: false)));
            sb.Append(Describe($"preset {kind} + lists", Preset(kind, extras: true)));
            sb.Append(Describe($"{kind} base, all on", With(kind, _ => true, extras: false)));
            sb.Append(Describe($"{kind} base, all on + lists", With(kind, _ => true, extras: true)));
            sb.Append(Describe($"{kind} base, all off + lists", With(kind, _ => false, extras: true)));
        }
        foreach (var kind in new[] { ProfileKind.Maximum, ProfileKind.Stream })
            foreach (var id in BaselineOptionIds)
            {
                sb.Append(Describe($"{kind} base, only {id}", With(kind, x => x == id, extras: false)));
                sb.Append(Describe($"{kind} base, only {id} + lists", With(kind, x => x == id, extras: true)));
            }
        foreach (var pair in new[] { ("proc.trayauto", "proc.windowed"), ("proc.tray", "proc.trayauto"), ("proc.tray", "proc.windowed"), ("proc.dpi", "proc.vpn") })
            sb.Append(Describe($"Maximum base, only {pair.Item1} + {pair.Item2}", With(ProfileKind.Maximum, x => x == pair.Item1 || x == pair.Item2, extras: false)));
        return sb.ToString().Replace("\r\n", "\n");
    }

    [Fact]
    public void What_the_planner_closes_and_stops_is_exactly_what_v2_0_0_closed_and_stopped()
    {
        var actual = Everything();
        var dir = Path.Combine(AppContext.BaseDirectory, "Golden");
        Directory.CreateDirectory(dir);
        File.WriteAllText(Path.Combine(dir, "selection.actual.txt"), actual);

        var goldenFile = Path.Combine(dir, "selection.golden.txt");
        Assert.True(File.Exists(goldenFile), "selection.golden.txt is missing: generate it from the v2.0.0 code (copy selection.actual.txt)");
        var expected = File.ReadAllText(goldenFile).Replace("\r\n", "\n");
        Assert.Equal(expected, actual);
    }

    [Fact]
    public void The_golden_machine_really_exercises_every_name_and_rule_of_the_catalog()
    {
        // guards the golden test itself: the sample machine contains every exact name of the catalog and the plan of "everything on" closes a lot of it
        var machine = BuildMachine();
        var names = machine.Procs.Select(p => ProtectedList.Normalize(p.Name)).ToHashSet();
        foreach (var cat in Catalog.ProcessCategories)
            foreach (var n in cat.Names)
                Assert.Contains(ProtectedList.Normalize(n), names);
        var plan = new Planner(machine).Build(With(ProfileKind.Maximum, _ => true, extras: false), TestEnv.Cs2Path);
        Assert.True(plan.Active.Count(a => a.Kind == ActionKind.CloseProcess) > 100);
        Assert.True(plan.Active.Count(a => a.Kind == ActionKind.StopService) >= 8);
    }
}
